export function load(){try{const raw=localStorage.getItem(KEY);if(raw){const db=JSON.parse(raw);if(db.version===1){for(const ext of ['webm','ogg','m4a'])if(!db.settings.extensions.split(',').includes(ext))db.settings.extensions+=','+ext;return db;}}}catch{}return seed();}
export function persist(db){localStorage.setItem(KEY,JSON.stringify(db));}
export function grade(value,scale='80:A+,70:A,60:A-,50:B,40:C,33:D,0:F'){return scale.split(',').map(x=>x.split(':')).sort((a,b)=>Number(b[0])-Number(a[0])).find(([n])=>value>=Number(n))?.[1]||'F';}
export function outstanding(db,studentId,period=month()){const s=db.students.find(x=>x.id===studentId);if(!s)return 0;return s.batchIds.reduce((sum,id)=>{const b=db.batches.find(x=>x.id===id&&x.status==='Active');return sum+Math.max(0,Number(b?.fee||0)-db.payments.filter(p=>p.studentId===studentId&&p.batchId===id&&p.month===period).reduce((n,p)=>n+Number(p.amount),0));},0);}
export function attendanceRate(records){return records.length?Math.round(records.filter(x=>x.status!=='Absent').length/records.length*100):0;}
export function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
export function csv(rows){return '\ufeff'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');}
